import {CASE,rooms,roomIds,evidence,items,puzzles,milestones,useRules} from './case.js';
import {fresh,apply,restore,unlocked,progress,roomProgress,available,missing,candidateLinks} from './engine.js';
const $=id=>document.getElementById(id),KEY='danchu-case-001-v4';
let raw=null,storageOK=true;try{raw=JSON.parse(localStorage.getItem(KEY)||'null');}catch{storageOK=false;}
let state=restore(raw),tab='inspect',focus=null,selectedSpot=null,selectedNotes=[],selectedItems=[],showMarkers=true,puzzleId=null,piano='',hintStep=0,sound=false,audio=null,motionTimer=null,drag=null;
const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}}
function say(text){$('feedback').textContent=text;}
function spriteIndex(index){return `background-position:${(index%4)/3*100}% ${Math.floor(index/4)/3*100}%;`;}
function tile(index,cls='',content=''){return `<div class="art-tile ${cls}" style="${spriteIndex(index)}" aria-hidden="true">${content}</div>`;}
function dial(minutes=13){const hr=minutes/2;return `<circle cx="50" cy="50" r="48" fill="#f5e9d1" stroke="#8a744f" stroke-width="2"/>${Array.from({length:12},(_,i)=>`<path d="M50 6v5" stroke="#8e8266" stroke-width="1.8" transform="rotate(${i*30} 50 50)"/>`).join('')}<path d="M50 50V22" stroke="#655c45" stroke-width="3.8" stroke-linecap="round" transform="rotate(${hr} 50 50)"/><path d="M50 50V11" stroke="#655c45" stroke-width="2.4" stroke-linecap="round" transform="rotate(${minutes*6} 50 50)"/><circle cx="50" cy="50" r="3" fill="#a38b57"/>`;}
function timeOverlay(id){if(id!=='wallclock'&&id!=='watch')return '';const m=id==='watch'?10:13;return `<svg class="dial-overlay" viewBox="0 0 100 100">${dial(m)}</svg><span class="reading-badge">판독값 · 00:${m}</span>`;}
function ping(freq=660,duration=.2,force=false){if(!sound&&!force)return;try{audio ||=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.045,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+duration+.02);}catch{}}
function send(a,{notice=true,refresh=true}={}){const r=apply(state,a);state=r.state;if(r.view){focus=r.view;tab='inspect';}if(refresh)render();if(notice&&r.message)say(r.message);if(r.changed)save();return r;}
function pose(index){$('actor-sprite').style.backgroundPosition=`${(index%4)/3*100}% ${Math.floor(index/4)*100}%`;$('actor').classList.toggle('pose-sleep',index===4);$('actor').classList.toggle('pose-gaze',index===5);$('actor').classList.toggle('pose-inspect',index===6);$('actor').setAttribute('aria-label',`단추 · ${['서 있기','생각하기','왼쪽으로 걷기','오른쪽으로 걷기','이불 덮고 잠들기','두 손으로 빛을 가리고 하늘 보기','돋보기로 살펴보기','놀라기'][index]}`);}
function actorPosition(){const a=state.actor;$('actor').style.left=a.x+'%';$('actor').style.top=a.y+'%';pose(a.pose);}
function walk(x,y,finalPose=0,callback){clearTimeout(motionTimer);const a=$('actor'),old=state.actor;const duration=reduced?0:Math.min(1250,Math.max(450,Math.abs(old.x-x)*14));pose(x<old.x?2:3);a.classList.add('walking');a.style.transition=`left ${duration}ms linear, top ${duration}ms linear`;a.style.left=x+'%';a.style.top=y+'%';motionTimer=setTimeout(()=>{motionTimer=null;a.classList.remove('walking');a.style.transition='none';const r=send({type:'actor',x,y,pose:finalPose},{notice:false,refresh:false});actorPosition();if(r.view||focus?.kind==='actor'){renderPanel();renderQuestions();renderTop();if(r.view)say(r.message);}if(callback)callback();},duration);}
function actAt(spot){const finalPose=spot.action==='sleep'?4:spot.action==='gaze'?5:spot.action==='crouch'?6:1;const y=spot.action==='sleep'?64:spot.action==='gaze'?73:82;walk(Math.max(10,Math.min(90,spot.x)),y,finalPose,()=>{$('dialogue').textContent=finalPose===4?'단추가 침대에 몸을 누이고 이불을 덮었다. 잠시 쉬어도 발견한 사실은 그대로 남는다.':finalPose===5?'단추는 두 손으로 주변 빛을 가리고, 유리 너머의 하늘을 올려다본다.':finalPose===6?'몸을 낮추고 돋보기로 흔적의 가장자리를 자세히 살핀다.':rooms[state.room].mood;});}
function inspect(id){const spot=rooms[state.room].hotspots.find(h=>h.id===id);if(!spot)return;selectedSpot=id;
 if(selectedItems.length===1&&spot.use){const r=send({type:'use',item:selectedItems[0],target:id});if(r.changed){selectedItems=[];renderPanel();}actAt(spot);return;}
 const r=send({type:'inspect',id});if(!r.view)focus={kind:'spot',id};tab='inspect';renderPanel();renderSelection();if(r.changed||!spot.requires||state.flags[spot.requires])actAt(spot);}
function renderTop(){const count=progress(state);$('progress').textContent=`${count} / 30`;$('progress-bar').style.width=count/30*100+'%';$('room-tag').textContent=rooms[state.room].tag;$('room-progress').textContent=`${rooms[state.room].name} · ${roomProgress(state,state.room)} / 5 조사 목표`;$('evidence-count').textContent=state.evidence.length;$('bag-count').textContent=state.inventory.length;$('next-room').hidden=!rooms[state.room].next||!unlocked(state,rooms[state.room].next);$('room-nav').innerHTML=roomIds.map((id,i)=>`<button data-room="${id}" class="${id===state.room?'active ':''}${roomProgress(state,id)===5?'solved':''}" ${!unlocked(state,id)?'disabled':''}>${String(i+1).padStart(2,'0')} ${rooms[id].name}${!unlocked(state,id)?' · 잠김':''}</button>`).join('');}
function renderSelection(){document.querySelectorAll('[data-hotspot]').forEach(b=>b.classList.toggle('selected',b.dataset.hotspot===selectedSpot));}
function renderScene(){const r=rooms[state.room];const img=$('room-image');if(!img.src.endsWith('/'+state.room+'.webp')){img.src=`case-art/${state.room}.webp`;img.alt=`${r.name} · 따뜻한 조명의 2D 조사 공간`;}$('exact-clock').hidden=state.room!=='bedroom';$('exact-clock').innerHTML=dial(13);$('hotspots').innerHTML=r.hotspots.map(h=>`<button class="hotspot ${state.observed.includes(state.room+':'+h.id)?'observed':''} ${h.id===selectedSpot?'selected':''}" data-hotspot="${h.id}" style="left:${h.x}%;top:${h.y}%" aria-label="${h.label}"><span>${h.label}</span></button>`).join('');$('scene-places').innerHTML=r.hotspots.map(h=>`<button data-hotspot="${h.id}" ${h.id===selectedSpot?'class="selected"':''}>${h.label}</button>`).join('');$('scene').classList.toggle('hide-markers',!showMarkers);if(!motionTimer)actorPosition();}
const milestoneLabels={curve:'냉각 기록 조사',temperature:'현재 온도 확인',elapsed:'경과 시간 추론',blackout:'정전 시각 복원',bedroom_open:'안쪽 문 열기',seal:'창문 봉인 관찰',footprints:'발자국 관찰',window_route:'창문 경로 검증',star_chart:'성도 조사',observatory_open:'방위 잠금 해결',blueprint:'시계 도면 조사',relay:'릴레이 조사',clock_method:'가짜 시각 해명',tool_made:'도구 조합',workshop_open:'서비스 통로 열기',ledger:'출입대장 조사',calibration:'시계 보정 확인',cart_time:'카트 시각 보정',archive_order:'기록 순서 복원',archive_open:'음악실 열기',splice:'녹음 접합부 관찰',score:'악보 조사',recording_loop:'녹음 시각 검증',tune:'선율 잠금 해제',music_open:'온실 문 열기',route:'운행표 조사',letter:'편지 조사',timeline:'실제 연표 복원',exit_method:'이동 경로 입증',case_closed:'사건의 전모 확정'};
function facts(id){if(id==='ledger')return '<table class="evidence-table"><tr><th>기록</th><th>타각 시각</th><th>내용</th></tr><tr><td>A</td><td>00:08</td><td>야간 점검</td></tr><tr><td>B</td><td>23:35</td><td>설비 기록</td></tr><tr><td>C</td><td>23:52</td><td>운반카트 진입</td></tr><tr><td>D</td><td>00:21</td><td>폐문 점검</td></tr></table>';if(id==='score')return '<table class="evidence-table"><tr><td>도</td><td>레</td><td>미</td><td>솔</td></tr><tr><td>1</td><td>2</td><td>3</td><td>5</td></tr></table>';if(id==='temperature')return '<div class="room-todo">센서 판독: <b>24°C</b><br>정상 온도: 30°C</div>';if(id==='watch')return '<div class="room-todo">독립 기준 시각: <b>00:10</b><br>관찰 기준은 고정되어 있습니다.</div>';return '';}
function currentSpot(){return rooms[state.room].hotspots.find(h=>h.id===selectedSpot);}
function spotActions(spot){if(!spot)return '';let html='';if(spot.action)html+=`<button class="action-button" data-actor-action="${spot.id}">${spot.action==='sleep'?'단추를 침대에 눕히기':spot.action==='gaze'?'단추로 하늘 살펴보기':'단추로 바닥 자세히 살펴보기'}</button>`;
 if(spot.use){const open=state.flags[spot.use];html+=`<button class="action-button" data-use-target="${spot.id}" ${open?'disabled':''}>${open?'통로를 열었습니다':selectedItems.length===1?items[selectedItems[0]].name+' 사용하기':'소지품에서 사용할 도구 고르기'}</button>`;}
 if(spot.door)html+=`<button class="action-button" data-enter="${spot.door}" ${!unlocked(state,spot.door)?'disabled':''}>${rooms[spot.door].name}로 이동 ${unlocked(state,spot.door)?'→':'· 아직 잠김'}</button>`;
 return html;}
function renderPanel(){document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===tab)));const panel=$('panel');
 if(tab==='notes'){panel.innerHTML=`<p class="note-intro">기록한 사실 두 개를 골라 연결하세요. 카드 이름을 다시 누르면 선택이 해제됩니다.</p><div class="note-grid">${state.evidence.map(id=>{const e=evidence[id];return `<button class="note-card ${selectedNotes.includes(id)?'selected':''}" data-note="${id}">${tile(e.art)}<span><b>${e.title}</b><small>${rooms[e.room].name}</small></span>${selectedNotes.includes(id)?'<span class="check">✓</span>':''}</button>`;}).join('')||'<p class="inspect-text">아직 기록한 증거가 없습니다. 방 안의 조사 대상을 선택하세요.</p>'}</div><div class="note-controls"><p>${selectedNotes.length} / 2 증거 선택</p><button class="action-button" id="connect-notes" ${selectedNotes.length!==2?'disabled':''}>선택한 증거 연결하기 →</button>${selectedNotes.length===1?'<button class="secondary" id="read-note">선택한 기록 다시 읽기</button>':''}</div>`;return;}
 if(tab==='bag'){panel.innerHTML=`<p class="note-intro">하나를 골라 장치에 사용하거나, 두 도구를 골라 조합하세요.</p><div class="bag-grid">${state.inventory.map(id=>`<button class="bag-item ${selectedItems.includes(id)?'selected':''}" data-bag-item="${id}">${tile(items[id].art)}<b>${items[id].name}</b></button>`).join('')||'<p class="inspect-text">조사 중 가져갈 수 있는 물건이 여기에 모입니다.</p>'}</div><div class="bag-caption">${selectedItems.length===1?items[selectedItems[0]].desc:selectedItems.length===2?'두 물건의 성질을 합치면 지금 필요한 도구가 될까요?':'아직 선택한 도구가 없습니다.'}</div><div class="bag-controls"><button id="combine-items" ${selectedItems.length!==2?'disabled':''}>두 도구 조합</button><button id="clear-items">선택 해제</button></div>${selectedItems.length===1?'<p class="note-intro" style="margin-top:15px">이제 장면의 장치를 누르면 선택한 도구를 사용할 수 있습니다.</p>':''}`;return;}
 const spot=currentSpot();if(!focus){panel.innerHTML=`<div class="empty-panel"><span class="eyebrow">${rooms[state.room].tag}</span><h2>가까이 보고,<br>서로 대조하기.</h2><p>${rooms[state.room].intro}</p><div class="room-todo">${milestones[roomIds.indexOf(state.room)].map(k=>`${state.flags[k]?'✓':'○'} ${milestoneLabels[k]}`).join('<br>')}</div><button class="secondary" data-tab-jump="notes">기록한 증거 살펴보기</button></div>`;return;}
 if(focus.kind==='actor'){const index=state.actor.pose;panel.innerHTML=`<div class="hero-preview" style="background-position:${(index%4)/3*100}% ${Math.floor(index/4)*100}%"></div><span class="fact-tag">단추 · 현장 반응</span><h2 class="inspect-heading">지금은 ${['주변을 살피는 중','생각하는 중','왼쪽으로 걷는 중','오른쪽으로 걷는 중','이불 덮고 쉬는 중','두 손으로 빛을 가리고 하늘을 보는 중','돋보기로 조사하는 중','새로운 사실에 놀란 중'][index]}</h2><p class="inspect-text">단추를 끌어 이동하거나 바닥을 눌러 움직일 수 있습니다. 장소에 따라 자세와 표정이 달라집니다.</p>${rooms[state.room].hotspots.filter(h=>h.action).map(h=>`<button class="action-button" data-actor-action="${h.id}">${h.label}에서 ${h.action==='sleep'?'이불 덮고 쉬기':h.action==='gaze'?'하늘 살펴보기':'가까이 조사하기'}</button>`).join('')}`;return;}
 if(focus.kind==='evidence'){const e=evidence[focus.id];panel.innerHTML=`${tile(e.art,'inspect-art',timeOverlay(focus.id))}<span class="fact-tag">관찰 사실 · 노트에 기록됨</span><h2 class="inspect-heading">${e.title}</h2><p class="inspect-text">${e.text}</p>${facts(focus.id)}<p class="inspect-detail">${e.detail}</p><button class="action-button" data-tab-jump="notes">다른 증거와 연결하기 →</button>${spotActions(spot)}`;return;}
 if(focus.kind==='item'){const i=items[focus.id];panel.innerHTML=`${tile(i.art,'inspect-art')}<span class="fact-tag">도구 · 형태와 기능</span><h2 class="inspect-heading">${i.name}</h2><p class="inspect-text">${i.desc}</p><button class="action-button" data-take="${focus.id}" ${state.inventory.includes(focus.id)?'disabled':''}>${state.inventory.includes(focus.id)?'이미 소지품에 있습니다':'소지품에 넣기'}</button><button class="secondary" data-tab-jump="bag">소지품 확인</button>`;return;}
 if(focus.kind==='deduction'){const p=puzzles[focus.id];panel.innerHTML=`<span class="fact-tag">증거에 근거한 추론 · 확정</span><h2 class="inspect-heading">${p.title}</h2><p class="inspect-text">${p.explain}</p><div class="puzzle-refs">${p.pair.map(id=>`<span>${evidence[id].title}</span>`).join('')}</div><button class="secondary" data-tab-jump="notes">조사 노트로 돌아가기</button>`;return;}
 if(focus.kind==='puzzle'){const p=puzzles[focus.id];panel.innerHTML=`${tile(spot?.art??0,'inspect-art')}<span class="fact-tag">조사할 장치</span><h2 class="inspect-heading">${p.title}</h2><p class="inspect-text">${p.question}</p><button class="action-button" data-puzzle="${focus.id}">${state.flags[p.flag]?'확정한 추리 다시 보기':'장치 조작 · 추리 확인'}</button>${spotActions(spot)}`;return;}
 if(spot){panel.innerHTML=`${spot.art!==undefined?tile(spot.art,'inspect-art'):''}<span class="fact-tag">${rooms[state.room].name} · 현장 조사</span><h2 class="inspect-heading">${spot.label}</h2><p class="inspect-text">${spot.player?'납통을 재생하면 네 음을 들을 수 있습니다. 소리를 사용할 수 없으면 같은 내용을 기록으로 확인하세요.':spot.action==='sleep'?'단추가 잠시 누울 수 있는 침대입니다. 이불을 덮고 쉴 수 있습니다.':spot.action==='gaze'?'단추를 창가로 옮기면 두 손으로 빛을 가리고 하늘을 바라봅니다.':'형태와 연결 부위를 살펴보고, 사용할 수 있는 도구가 있는지 생각해 보세요.'}</p>${spot.player?'<button class="action-button" id="play-recording">납통 재생 · 소리 듣기 ♪</button><button class="secondary" id="read-recording">소리 대신 기록 보기</button>':''}${spotActions(spot)}`;}
}
function renderQuestions(){const ids=Object.keys(puzzles).filter(id=>{const p=puzzles[id];return p.requires.some(k=>state.evidence.includes(k)||state.flags[k])||state.flags[p.flag];});$('question-list').innerHTML=ids.map(id=>{const p=puzzles[id],done=state.flags[p.flag],ready=available(state,id);return `<button class="question-card ${done?'solved':!ready?'locked':''}" data-puzzle="${id}"><b>${done?'✓ ':''}${p.title}</b><small>${done?'근거와 함께 확정됨':ready?'증거가 모였습니다 · 추리하기':'추가 관찰이 필요합니다'}</small></button>`;}).join('')||'<p class="inspect-text">두 개 이상의 단서를 조사하면 연결할 질문이 생깁니다.</p>';}
function render(){renderTop();renderScene();renderPanel();renderQuestions();save();}
function requirementName(id){return evidence[id]?.title||milestoneLabels[id]||id;}
function openPuzzle(id){const p=puzzles[id];if(!p)return;puzzleId=id;piano='';let content=`<h2>${p.title}</h2><p>${p.question}</p><div class="puzzle-refs">${p.requires.map(k=>`<span class="${state.evidence.includes(k)||state.flags[k]?'':'missing'}">${state.evidence.includes(k)||state.flags[k]?'✓ ':'○ '}${requirementName(k)}</span>`).join('')}</div>`;
 if(state.flags[p.flag])content+=`<div class="room-todo">${p.explain}</div>`;
 else if(!available(state,id))content+='<p class="room-todo">점선으로 표시된 근거를 먼저 확인하세요. 관찰과 추리를 구분해 진행합니다.</p>';
 else if(p.type==='choice')content+=`<div class="choice-list">${p.options.map(([value,label])=>`<button data-answer="${value}">${label}</button>`).join('')}</div>`;
 else if(p.type==='code')content+=`<form class="code-form" id="code-form"><input id="code-input" autocomplete="off" autocapitalize="characters" maxlength="4" aria-label="${p.title} 네 자리 입력" ${id==='blackout'?'inputmode="numeric"':''}><button type="submit">확인</button></form>`;
 else if(p.type==='notes')content+='<div class="piano-readout" id="piano-readout">— — — —</div><div class="piano-keys"><button data-note-key="1">도<br><small>1</small></button><button data-note-key="2">레<br><small>2</small></button><button data-note-key="3">미<br><small>3</small></button><button data-note-key="5">솔<br><small>5</small></button></div><div class="mini-actions"><button id="clear-piano">처음부터</button><button id="piano-transcript">녹음 기록 다시 보기</button></div>';
 $('puzzle-content').innerHTML=content;$('puzzle-feedback').textContent='';if(!$('puzzle-dialog').open)$('puzzle-dialog').showModal();setTimeout(()=>$('code-input')?.focus(),30);}
function answer(value){const r=send({type:'solve',id:puzzleId,answer:value});$('puzzle-feedback').textContent=r.message;if(r.changed){ping(784);pose(7);if(state.flags.case_closed){$('puzzle-dialog').close();$('ending-copy').textContent=puzzles.conclusion.explain;$('ending-dialog').showModal();}else openPuzzle(puzzleId);}else{pose(1);if(puzzles[puzzleId]?.type==='notes'){piano='';const read=$('piano-readout');if(read)read.textContent='— — — —';}}}
function listen(playSound){send({type:'listen'});if(playSound)[261.63,329.63,293.66,392].forEach((f,i)=>setTimeout(()=>ping(f,.34,true),i*510));}
function changeRoom(id){const r=send({type:'room',room:id});if(r.changed){clearTimeout(motionTimer);motionTimer=null;focus=null;selectedSpot=null;selectedItems=[];selectedNotes=[];tab='inspect';hintStep=0;$('dialogue').textContent=rooms[id].intro;render();window.scrollTo({top:0,behavior:'instant'});}}
// Delegated controls keep notebook/inspector replacements accessible and deterministic.
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;
 if(el.dataset.hotspot){inspect(el.dataset.hotspot);return;}
 if(el.dataset.room){changeRoom(el.dataset.room);return;}
 if(el.dataset.tab){tab=el.dataset.tab;renderPanel();return;}
 if(el.dataset.tabJump){tab=el.dataset.tabJump;renderPanel();return;}
 if(el.dataset.puzzle){openPuzzle(el.dataset.puzzle);return;}
 if(el.dataset.answer!==undefined){answer(el.dataset.answer);return;}
 if(el.dataset.noteKey){piano+=el.dataset.noteKey;ping({1:261.63,2:293.66,3:329.63,5:392}[el.dataset.noteKey],.28,true);$('piano-readout').textContent=piano.split('').join(' ');if(piano.length===4)answer(piano);return;}
 if(el.dataset.note){const id=el.dataset.note;selectedNotes=selectedNotes.includes(id)?selectedNotes.filter(v=>v!==id):[...selectedNotes.slice(-1),id];renderPanel();return;}
 if(el.dataset.bagItem){const id=el.dataset.bagItem;selectedItems=selectedItems.includes(id)?selectedItems.filter(v=>v!==id):[...selectedItems.slice(-1),id];renderPanel();return;}
 if(el.dataset.take){const r=send({type:'take',item:el.dataset.take});if(r.changed)ping();return;}
 if(el.dataset.actorAction){const spot=rooms[state.room].hotspots.find(h=>h.id===el.dataset.actorAction);if(spot)actAt(spot);return;}
 if(el.dataset.useTarget){if(selectedItems.length!==1){tab='bag';renderPanel();say('도구 하나를 선택한 뒤 장치를 다시 누르세요.');}else{const r=send({type:'use',item:selectedItems[0],target:el.dataset.useTarget});if(r.changed){selectedItems=[];renderPanel();}}return;}
 if(el.dataset.enter){changeRoom(el.dataset.enter);return;}
 if(el.dataset.close){$(el.dataset.close).close();return;}
 switch(el.id){
 case 'connect-notes':{const matches=candidateLinks(state,selectedNotes);if(matches.length===1)openPuzzle(matches[0]);else if(matches.length>1){$('puzzle-content').innerHTML='<h2>같은 기록, 다른 질문</h2><p>선택한 두 증거로 확인할 질문을 고르세요.</p>'+matches.map(id=>`<button class="action-button" data-puzzle="${id}">${puzzles[id].title}${state.flags[puzzles[id].flag]?' · 확정':''}</button>`).join('');$('puzzle-feedback').textContent='';$('puzzle-dialog').showModal();}else say('이 두 사실만으로 확정할 연결은 아직 없습니다. 각각의 관찰을 다시 읽어 보세요.');break;}
 case 'read-note':focus={kind:'evidence',id:selectedNotes[0]};tab='inspect';renderPanel();break;
 case 'combine-items':{const r=send({type:'combine',items:selectedItems});if(r.changed){selectedItems=[];ping();renderPanel();}break;}
 case 'clear-items':selectedItems=[];renderPanel();break;
 case 'play-recording':listen(true);break;case 'read-recording':listen(false);break;
 case 'clear-piano':piano='';$('piano-readout').textContent='— — — —';break;
 case 'piano-transcript':$('puzzle-feedback').textContent=evidence.recording.text;break;
 case 'next-room':changeRoom(rooms[state.room].next);break;
 case 'pose-idle':clearTimeout(motionTimer);motionTimer=null;send({type:'actor',x:state.actor.x,y:state.actor.y,pose:0},{notice:false});$('dialogue').textContent=rooms[state.room].mood;break;
 case 'markers':showMarkers=!showMarkers;$('markers').textContent=showMarkers?'조사 위치 ON':'조사 위치 OFF';$('markers').setAttribute('aria-pressed',String(showMarkers));$('scene').classList.toggle('hide-markers',!showMarkers);break;
 case 'hint':{const h=rooms[state.room].hint;hintStep=Math.min(hintStep+1,h.length);state.hints++;say(`힌트 ${hintStep}/${h.length} · ${h[hintStep-1]}`);save();break;}
 case 'sound':sound=!sound;$('sound').textContent=sound?'♪ ON':'♪ OFF';$('sound').setAttribute('aria-pressed',String(sound));if(sound)ping();break;
 case 'help':$('about-dialog').showModal();break;
 }
});
document.addEventListener('submit',e=>{if(e.target.id==='code-form'){e.preventDefault();answer($('code-input').value);}});
$('case-about').onclick=e=>{e.preventDefault();$('about-dialog').showModal();};
$('scene').addEventListener('click',e=>{if(e.target.closest('[data-hotspot],#actor')||drag)return;const r=$('scene').getBoundingClientRect(),x=(e.clientX-r.left)/r.width*100,y=(e.clientY-r.top)/r.height*100;walk(Math.max(8,Math.min(92,x)),Math.max(61,Math.min(90,y)),0);});
const actor=$('actor');actor.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.stopPropagation();clearTimeout(motionTimer);motionTimer=null;drag={pointer:e.pointerId,startX:e.clientX,startY:e.clientY,moved:false};actor.style.transition='none';actor.setPointerCapture(e.pointerId);});
actor.addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;const r=$('scene').getBoundingClientRect();if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>7)drag.moved=true;if(drag.moved){actor.style.left=Math.max(8,Math.min(92,(e.clientX-r.left)/r.width*100))+'%';actor.style.top=Math.max(53,Math.min(90,(e.clientY-r.top)/r.height*100))+'%';pose(e.clientX<drag.startX?2:3);}});
actor.addEventListener('pointerup',e=>{if(!drag||drag.pointer!==e.pointerId)return;e.stopPropagation();const d=drag;drag=null;if(actor.hasPointerCapture(e.pointerId))actor.releasePointerCapture(e.pointerId);if(!d.moved){send({type:'actor',x:state.actor.x,y:state.actor.y,pose:state.actor.pose===1?0:1},{notice:false,refresh:false});actorPosition();focus={kind:'actor'};tab='inspect';renderPanel();return;}const r=$('scene').getBoundingClientRect(),x=Math.max(8,Math.min(92,(e.clientX-r.left)/r.width*100)),y=Math.max(53,Math.min(90,(e.clientY-r.top)/r.height*100));const place=rooms[state.room].hotspots.filter(h=>h.action).find(h=>Math.abs(h.x-x)<19&&(h.action==='sleep'||h.action==='gaze')&&y<83);if(place)actAt(place);else send({type:'actor',x,y,pose:0},{notice:false});});
function cancelDrag(){if(drag){drag=null;actorPosition();}}actor.addEventListener('pointercancel',cancelDrag);actor.addEventListener('lostpointercapture',cancelDrag);actor.addEventListener('keydown',e=>{const k=e.key;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(k)){e.preventDefault();const x=state.actor.x+(k==='ArrowLeft'?-5:k==='ArrowRight'?5:0),y=state.actor.y+(k==='ArrowUp'?-4:k==='ArrowDown'?4:0);walk(Math.max(8,Math.min(92,x)),Math.max(53,Math.min(90,y)),0);}if(k==='Enter'||k===' '){e.preventDefault();send({type:'actor',x:state.actor.x,y:state.actor.y,pose:1},{notice:false,refresh:false});actorPosition();focus={kind:'actor'};tab='inspect';renderPanel();say('장면의 침대나 창가 버튼으로 단추의 장소별 동작을 볼 수 있습니다.');}});
render();$('dialogue').textContent=rooms[state.room].intro;if(!raw)$('about-dialog').showModal();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
